mapper.select:
SELECT COUNT(*) FROM T_TASK AS task, T_FLIGHT AS flight LEFT JOIN T_FLIGHT tf2 ON IF ( tf2.flgt_a_atot is not null, tf2.flgt_a_atot > DATE_ADD(CURDATE(),INTERVAL 0 HOUR), tf2.flgt_a_stot > DATE_ADD(CURDATE(),INTERVAL 0 HOUR) ) AND tf2.flgt_adid = 'A' AND flight.flgt_airport_code = tf2.flgt_airport_code AND ((flight.flgt_link_flno IS NOT NULL AND flight.flgt_link_flno <> '' AND tf2.flgt_flno LIKE CONCAT('%',flight.flgt_link_flno,'%'))) AND ((tf2.flgt_link_flno IS NOT NULL AND tf2.flgt_link_flno <> '' AND flight.flgt_flno LIKE CONCAT('%',tf2.flgt_link_flno,'%'))) AND flight.flgt_regn = tf2.flgt_regn AND flight.flgt_link_flop = tf2.flgt_flop AND flight.flgt_flop = tf2.flgt_link_flop AND flight.flgt_repeat = tf2.flgt_link_repeat AND flight.flgt_link_repeat = tf2.flgt_repeat WHERE task.task_flight_id = flight.flgt_id AND flight.flgt_ftyp <> 'NO' AND flight.flgt_ftyp <> 'CX' AND flight.flgt_adid = 'D' AND IF ( flight.flgt_d_etot is null, flight.flgt_d_stot >= DATE_ADD(#{date},INTERVAL 4 HOUR) AND flight.flgt_d_stot < DATE_ADD(#{date},INTERVAL 28 HOUR), flight.flgt_d_etot >= DATE_ADD(#{date},INTERVAL 4 HOUR) AND flight.flgt_d_etot < DATE_ADD(#{date},INTERVAL 28 HOUR) ) AND flight.flgt_airport_code = #{staffAirportCode}
and flight.flgt_aptarea_code = #{staffAptareaCode}
ORDER BY flight.flgt_num ASC

SELECT task.task_id AS taskId, task.task_ope_staff_id AS taskOpeStaffId, task.task_content AS taskContent, task.task_status AS taskStatus, task.task_asg_time AS taskAsgTime, task.task_acc_time AS taskAccTime, task.task_chag_sta_time AS taskChagStaTime, task.task_chag_end_time AS taskChagEndTime, task.task_done_time AS taskDoneTime, task.task_fuel_recpt_no AS taskFuelRecptNo, task.task_vehi_no AS taskVehiNo, task.task_cre_staff_id AS taskCreStaffId, task.task_starmark AS taskStarmark, task.task_rec_cre_time AS taskRecCreTime, task.task_takeoff_fuel as flgtTakeoffFuel, task.task_chock_fuel as flgtChockFuel, flight.flgt_id AS flgtId, flight.flgt_ffid AS flgtFfid, flight.flgt_airport_code AS flgtAirportCode, flight.flgt_aptarea_code AS flgtAptareaCode, flight.flgt_flno AS flgtFlno, flight.flgt_flop AS flgtFlop, flight.flgt_acname AS flgtAcname, flight.flgt_regn AS flgtRegn, flight.flgt_placecode AS flgtPlacecode, flight.flgt_al2c AS flgtAl2c, flight.flgt_alcname AS flgtAlcname, flight.flgt_d_stot AS flgtDStot, flight.flgt_d_etot AS flgtDEtot, flight.flgt_d_atot AS flgtDAtot, flight.flgt_org3c AS flgtOrg3c, flight.flgt_orgnm AS flgtOrgnm, flight.flgt_trs3c1 AS flgtTrs3c1, flight.flgt_trs3c2 AS flgtTrs3c2, flight.flgt_trs3c3 AS flgtTrs3c3, flight.flgt_trs3c4 AS flgtTrs3c4, flight.flgt_trs3c5 AS flgtTrs3c5, flight.flgt_trsnm1 AS flgtTrsnm1, flight.flgt_trsnm2 AS flgtTrsnm2, flight.flgt_trsnm3 AS flgtTrsnm3, flight.flgt_trsnm4 AS flightValic, flight.flgt_trsnm5 AS flgtVialc, flight.flgt_des3c AS flgtDes3c, flight.flgt_desnm AS flgtDesnm, flight.flgt_adid AS flgtAdid, flight.flgt_flti AS flgtFlti, flight.flgt_ftyp AS flgtFtyp, flight.flgt_proxy AS flgtProxy, flight.flgt_fnflag AS flgtFnflag, flight.flgt_game AS flgtGame, flight.flgt_chocks_in AS flgtChocksIn, flight.flgt_chocks_out AS flgtChocksOut, flight.flgt_vip AS flgtVip, flight.flgt_otc AS flgtOtc, flight.flgt_num AS flgtNum, flight.flgt_repeat AS flgtRepeat, flight.flgt_link_flop AS flgtLinkFlop, flight.flgt_link_repeat AS flgtLinkRepeat, flight.flgt_otc AS flgtOtc, flight.flgt_regn_status AS flgtRegnStatus, flight.flgt_placecode_status AS flgtPlacecodeStatus, flight.remark AS remark , flight.flgt_atax as flgtAtax, flight.flgt_mission_prop as flgtMissionProp, flight.flgt_ifsr AS flgtIfsr, tt.font_color AS flgtGate, tf2.flgt_flno AS flgtLinkFlno, tf2.flgt_org3c AS beorg3c, tf2.flgt_a_stot AS flgtAStot, tf2.flgt_a_etot AS flgtAEtot, tf2.flgt_a_atot AS flgtAAtot, tf2.flgt_flti AS flgtFltiIn, tf2.flgt_placecode AS flgtPlacecodeIn, tf2.flgt_ftyp AS aFlgtFtyp, tf2.flgt_mission_prop as flgtMissionPropIn FROM T_TASK AS task, T_FLIGHT AS flight left join T_PLACECODE t on t.place_code = flight.flgt_placecode LEFT JOIN T_PLACECODE_TYPE tt ON t.place_code_type=tt.id LEFT JOIN T_FLIGHT tf2 ON tf2.flgt_adid = 'A' AND flight.flgt_airport_code = tf2.flgt_airport_code AND ((flight.flgt_link_flno IS NOT NULL AND flight.flgt_link_flno <> '' AND tf2.flgt_flno LIKE CONCAT('%',flight.flgt_link_flno,'%'))) AND ((tf2.flgt_link_flno IS NOT NULL AND tf2.flgt_link_flno <> '' AND flight.flgt_flno LIKE CONCAT('%',tf2.flgt_link_flno,'%'))) AND flight.flgt_regn = tf2.flgt_regn AND flight.flgt_link_flop = tf2.flgt_flop AND flight.flgt_flop = tf2.flgt_link_flop AND flight.flgt_repeat = tf2.flgt_link_repeat AND flight.flgt_link_repeat = tf2.flgt_repeat WHERE task.task_flight_id = flight.flgt_id AND flight.flgt_ftyp <> 'NO' AND flight.flgt_ftyp <> 'CX' AND flight.flgt_ftyp <> 'DE' AND flight.flgt_adid = 'D' and flight.flgt_ftyp <> 'FX' AND IF( flight.flgt_d_etot IS NULL and flight.flgt_d_stot IS NULL, flight.flgt_flop = CURDATE(), IF ( flight.flgt_d_etot is null, flight.flgt_d_stot >= DATE_ADD(#{date},INTERVAL 4 HOUR) AND flight.flgt_d_stot < DATE_ADD(#{date},INTERVAL 28 HOUR), flight.flgt_d_etot >= DATE_ADD(#{date},INTERVAL 4 HOUR) AND flight.flgt_d_etot < DATE_ADD(#{date},INTERVAL 28 HOUR) ) ) AND flight.flgt_airport_code = #{staffAirportCode}
AND flight.flgt_aptarea_code = #{staffAptareaCode}
order by flight.flgt_num ASC

SELECT task.task_id AS taskId, task.task_ope_staff_id AS taskOpeStaffId, task.task_content AS taskContent, task.task_status AS taskStatus, task.task_asg_time AS taskAsgTime, task.task_acc_time AS taskAccTime, task.task_chag_sta_time AS taskChagStaTime, task.task_chag_end_time AS taskChagEndTime, task.task_done_time AS taskDoneTime, task.task_fuel_recpt_no AS taskFuelRecptNo, task.task_vehi_no AS taskVehiNo, task.task_cre_staff_id AS taskCreStaffId, task.task_starmark AS taskStarmark, task.task_rec_cre_time AS taskRecCreTime, task.task_takeoff_fuel as flgtTakeoffFuel, task.task_chock_fuel as flgtChockFuel, flight.flgt_id AS flgtId, flight.flgt_ffid AS flgtFfid, flight.flgt_airport_code AS flgtAirportCode, flight.flgt_aptarea_code AS flgtAptareaCode, flight.flgt_flno AS flgtFlno, flight.flgt_flop AS flgtFlop, flight.flgt_acname AS flgtAcname, flight.flgt_regn AS flgtRegn, flight.flgt_ifsr AS flgtIfsr, flight.flgt_placecode AS flgtPlacecode, flight.flgt_al2c AS flgtAl2c, flight.flgt_alcname AS flgtAlcname, flight.flgt_d_stot AS flgtDStot, flight.flgt_d_etot AS flgtDEtot, flight.flgt_d_atot AS flgtDAtot, flight.flgt_org3c AS flgtOrg3c, flight.flgt_orgnm AS flgtOrgnm, flight.flgt_trs3c1 AS flgtTrs3c1, flight.flgt_trs3c2 AS flgtTrs3c2, flight.flgt_trs3c3 AS flgtTrs3c3, flight.flgt_trs3c4 AS flgtTrs3c4, flight.flgt_trs3c5 AS flgtTrs3c5, flight.flgt_trsnm1 AS flgtTrsnm1, flight.flgt_trsnm2 AS flgtTrsnm2, flight.flgt_trsnm3 AS flgtTrsnm3, flight.flgt_trsnm4 AS flightValic, flight.flgt_trsnm5 AS flgtVialc, flight.flgt_des3c AS flgtDes3c, flight.flgt_desnm AS flgtDesnm, flight.flgt_adid AS flgtAdid, flight.flgt_flti AS flgtFlti, flight.flgt_ftyp AS flgtFtyp, flight.flgt_proxy AS flgtProxy, flight.flgt_fnflag AS flgtFnflag, flight.flgt_game AS flgtGame, flight.flgt_chocks_in AS flgtChocksIn, flight.flgt_chocks_out AS flgtChocksOut, flight.flgt_vip AS flgtVip, flight.flgt_otc AS flgtOtc, flight.flgt_num AS flgtNum, flight.flgt_repeat AS flgtRepeat, flight.flgt_link_flop AS flgtLinkFlop, flight.flgt_link_repeat AS flgtLinkRepeat, flight.flgt_otc AS flgtOtc, flight.flgt_regn_status AS flgtRegnStatus, flight.flgt_placecode_status AS flgtPlacecodeStatus, flight.remark AS remark , flight.flgt_atax as flgtAtax, flight.flgt_mission_prop as flgtMissionProp, flight.flgt_gate AS flgtGate, tf2.flgt_flno AS flgtLinkFlno, tf2.flgt_org3c AS beorg3c, tf2.flgt_a_stot AS flgtAStot, tf2.flgt_a_etot AS flgtAEtot, tf2.flgt_a_atot AS flgtAAtot, tf2.flgt_flti AS flgtFltiIn, tf2.flgt_placecode AS flgtPlacecodeIn, tf2.flgt_ftyp AS aFlgtFtyp, tf2.flgt_mission_prop as flgtMissionPropIn FROM T_TASK AS task, T_FLIGHT AS flight LEFT JOIN T_FLIGHT tf2 ON tf2.flgt_adid = 'A' AND flight.flgt_airport_code = tf2.flgt_airport_code AND ((flight.flgt_link_flno IS NOT NULL AND flight.flgt_link_flno <> '' AND tf2.flgt_flno LIKE CONCAT('%',flight.flgt_link_flno,'%'))) AND ((tf2.flgt_link_flno IS NOT NULL AND tf2.flgt_link_flno <> '' AND flight.flgt_flno LIKE CONCAT('%',tf2.flgt_link_flno,'%'))) AND flight.flgt_regn = tf2.flgt_regn AND flight.flgt_link_flop = tf2.flgt_flop AND flight.flgt_flop = tf2.flgt_link_flop AND flight.flgt_repeat = tf2.flgt_link_repeat AND flight.flgt_link_repeat = tf2.flgt_repeat WHERE task.task_flight_id = flight.flgt_id AND flight.flgt_ftyp <> 'NO' AND flight.flgt_ftyp <> 'CX' AND flight.flgt_ftyp <> 'DE' AND flight.flgt_adid = 'D' and flight.flgt_ftyp <> 'FX' AND IF( flight.flgt_d_etot IS NULL and flight.flgt_d_stot IS NULL, flight.flgt_flop = CURDATE(), IF ( flight.flgt_d_etot is null, flight.flgt_d_stot >= DATE_ADD(#{date},INTERVAL 0 HOUR) AND flight.flgt_d_stot <= DATE_ADD(#{date},INTERVAL 24 HOUR), flight.flgt_d_etot >= DATE_ADD(#{date},INTERVAL 0 HOUR) AND flight.flgt_d_etot <= DATE_ADD(#{date},INTERVAL 24 HOUR) ) ) AND flight.flgt_airport_code = #{staffAirportCode}
AND flight.flgt_aptarea_code = #{staffAptareaCode}
order by flight.flgt_num ASC

select task_ope_staff_id AS taskOpeStaffId
from T_TASK
where task_id = #{taskId}

select flight.flgt_placecode AS flgtPlacecode, task.task_id AS taskId, task.task_flight_id AS taskFlightId, task.task_flight_no AS taskFlightNo, task.task_airport_code AS taskAirportCode, task.task_aptarea_code AS taskAptareaCode, task.task_ope_staff_id AS taskOpeStaffId, task.task_content AS taskContent, task.task_status AS taskStatus, task.task_asg_time AS taskAsgTime, task.task_acc_time AS taskAccTime, task.task_chag_sta_time AS taskChagStaTime, task.task_chag_end_time AS taskChagEndTime, task.task_done_time AS taskDoneTime, task.task_fuel_recpt_no AS taskFuelRecptNo, task.task_vehi_no AS taskVehiNo, task.task_cre_staff_id AS taskCreStaffId, task.task_starmark AS taskStarmark, task.task_rec_cre_time AS taskRecCreTime from T_TASK task , T_FLIGHT flight where task.task_flight_id = flight.flgt_id and task.task_status <> 0 and task.task_status <> 7 and task.task_status <> 9 and task.task_airport_code = #{staffAirportCode}
and task.task_aptarea_code = #{staffAptareaCode}
ORDER BY task.task_asg_time desc

select flight.flgt_placecode AS flgtPlacecode, task.task_id AS taskId, task.task_flight_id AS taskFlightId, task.task_flight_no AS taskFlightNo, task.task_airport_code AS taskAirportCode, task.task_aptarea_code AS taskAptareaCode, task.task_ope_staff_id AS taskOpeStaffId, task.task_content AS taskContent, task.task_status AS taskStatus, task.task_asg_time AS taskAsgTime, task.task_acc_time AS taskAccTime, task.task_chag_sta_time AS taskChagStaTime, task.task_chag_end_time AS taskChagEndTime, task.task_done_time AS taskDoneTime, task.task_fuel_recpt_no AS taskFuelRecptNo, task.task_vehi_no AS taskVehiNo, task.task_cre_staff_id AS taskCreStaffId, task.task_starmark AS taskStarmark, task.task_rec_cre_time AS taskRecCreTime from T_TASK task , T_FLIGHT flight where task.task_flight_id = flight.flgt_id and task.task_status > 6 and task.task_airport_code = #{staffAirportCode}
and task.task_aptarea_code = #{staffAptareaCode}
ORDER BY task.task_asg_time desc

mapper.update:
update T_TASK
set task_status   = #{taskStatus},
    task_acc_time = #{taskAccTime},
    task_vehi_no  = #{vehiNo}
where task_id = #{taskId}

update T_TASK
set task_status        = #{taskStatus},
    task_vehi_no       =#{sfvhVehiNo},
    task_chag_sta_time = #{taskChagStaTime},
    task_arrive_time   = #{taskChagStaTime}
where task_id = #{taskId}

update T_TASK
set task_starmark = #{taskStarmark}
where task_id = #{taskId}

mapper.select:
select ta.task_id AS taskId, ta.task_flight_id AS taskFlightId, ta.task_flight_no AS taskFlightNo, ta.task_airport_code AS taskAirportCode, ta.task_aptarea_code AS taskAptareaCode, ta.task_ope_staff_id AS taskOpeStaffId, ta.task_content AS taskContent, ta.task_status AS taskStatus, ta.task_asg_time AS taskAsgTime, ta.task_acc_time AS taskAccTime, ta.task_chag_sta_time AS taskChagStaTime, ta.task_chag_end_time AS taskChagEndTime, ta.task_done_time AS taskDoneTime, ta.task_rc_print_time AS taskRcPrintTime, ta.task_fuel_recpt_no AS taskFuelRecptNo, ta.task_vehi_no AS taskVehiNo, ta.task_cre_staff_id AS taskCreStaffId, ta.task_starmark AS taskStarmark, ta.task_rec_cre_time AS taskRecCreTime, tf.flgt_alcname AS flgtAlcname, tf.flgt_placecode AS flgtPlacecode from T_TASK ta,T_FLIGHT tf where ta.task_flight_id = tf.flgt_id and tf.flgt_flop in (CURDATE(),DATE_SUB(CURDATE(),interval 1 day),DATE_SUB(CURDATE(),interval 2 day),DATE_SUB(CURDATE(),interval 3 day),DATE_SUB(CURDATE(),interval 4 day),DATE_SUB(CURDATE(),interval 5 day),DATE_SUB(CURDATE(),interval 6 day),DATE_SUB(CURDATE(),interval 7 day)) and ta.task_status <> 0 and ta.task_status <> 9
and ta.task_airport_code = #{staffAirportCode}
and ta.task_aptarea_code = #{staffAptareaCode}
order by ta.task_done_time desc

select
task_id AS taskId,
task_flight_id AS taskFlightId,
task_flight_no AS taskFlightNo,
task_airport_code AS taskAirportCode,
task_aptarea_code AS taskAptareaCode,
task_ope_staff_id AS taskOpeStaffId,
task_content AS taskContent,
task_status AS taskStatus,
task_asg_time AS taskAsgTime,
task_acc_time AS taskAccTime,
task_chag_sta_time AS taskChagStaTime,
task_chag_end_time AS taskChagEndTime,
task_done_time AS taskDoneTime,
task.task_rc_print_time AS taskRcPrintTime,
task_fuel_recpt_no AS taskFuelRecptNo,
task_vehi_no AS taskVehiNo,
task_cre_staff_id AS taskCreStaffId,
task_starmark AS taskStarmark,
task_rec_cre_time AS taskRecCreTime
from T_TASK where task_airport_code = #{staffAirportCode}

    and task_aptarea_code = #{staffAptareaCode}


    and task_flight_no = #{task.taskFlightNo}


    and task_content = #{task.taskContent}


    and task_status = #{task.taskStatus}


    and task_asg_time = #{task.taskAsgTime}


    and task_acc_time = #{task.taskAccTime}


    and task_chag_sta_time = #{task.taskChagStaTime}


    and task_chag_end_time = #{task.taskChagEndTime}


    and task_done_time = #{task.taskDoneTime}


    and task_fuel_recpt_no = #{task.taskFuelRecptNo}


    and task_vehi_no = #{task.taskVehiNo}


    and task_starmark = #{task.taskStarmark}


    and task_rec_cre_time = #{task.taskRecCreTime}

